import { ALLOWED_ATTRS, ALLOWED_TAGS, isBlockTag, isSafeUrl, isAllowedIframeSrc, isSafeStyleValue } from './Schema';

// Sanitizes an HTML string into a fragment safe to insert into the editable
// area: disallowed tags are unwrapped (children kept), disallowed attributes
// dropped, and unsafe URL schemes stripped from href/src.
export function sanitizeHtml(html: string): DocumentFragment {
  const template = document.createElement('template');
  template.innerHTML = html;
  sanitizeNode(template.content);
  return template.content;
}

function sanitizeNode(root: DocumentFragment | Element): void {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
  const toUnwrap: Element[] = [];
  let node = walker.nextNode() as Element | null;

  while (node) {
    const tag = node.tagName.toLowerCase();

    if (tag === 'script' || tag === 'style') {
      node.remove();
      node = walker.nextNode() as Element | null;
      continue;
    }

    if (tag === 'iframe') {
      const src = node.getAttribute('src') ?? '';
      if (!isAllowedIframeSrc(src)) {
        node.remove();
        node = walker.nextNode() as Element | null;
        continue;
      }
      sanitizeAttributes(node);
      // Never trust a sandbox value from input — always force our own
      // minimal, known-safe policy regardless of what was on the element.
      node.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-presentation');
      node = walker.nextNode() as Element | null;
      continue;
    }

    if (!ALLOWED_TAGS.has(tag)) {
      toUnwrap.push(node);
    } else {
      sanitizeAttributes(node);
    }

    node = walker.nextNode() as Element | null;
  }

  for (const el of toUnwrap) {
    const parent = el.parentNode;
    if (!parent) continue;
    while (el.firstChild) parent.insertBefore(el.firstChild, el);
    parent.removeChild(el);
  }
}

function sanitizeAttributes(el: Element): void {
  for (const attr of Array.from(el.attributes)) {
    const name = attr.name.toLowerCase();

    // data-* attributes are allowed generically (a safe, inert convention
    // used e.g. by the codesample plugin to round-trip original source
    // text) rather than needing each one added to ALLOWED_ATTRS by name.
    const isDataAttr = name.startsWith('data-');

    if (name.startsWith('on') || (!isDataAttr && !ALLOWED_ATTRS.has(name))) {
      el.removeAttribute(attr.name);
      continue;
    }

    if ((name === 'href' || name === 'src' || name === 'poster') && !isSafeUrl(attr.value)) {
      el.removeAttribute(attr.name);
      continue;
    }

    if (name === 'style' && !isSafeStyleValue(attr.value)) {
      el.removeAttribute(attr.name);
    }
  }
}

export function getContent(root: HTMLElement): string {
  return root.innerHTML.trim();
}

// Wraps any run of non-block children sitting directly under `root` (plain
// text, or inline elements like <strong>/<a>) in a <p>, so content set
// without its own block markup still lands in a real block — matching what
// a browser's contentEditable normally produces once the user starts typing,
// and giving plugins like elementpath a block to report instead of the
// content div itself.
export function wrapLooseInlineContent(root: HTMLElement): void {
  let run: ChildNode[] = [];

  const flush = () => {
    if (run.length === 0) return;
    const p = document.createElement('p');
    root.insertBefore(p, run[0]!);
    for (const node of run) p.appendChild(node);
    run = [];
  };

  for (const child of Array.from(root.childNodes)) {
    const isBlock = child.nodeType === Node.ELEMENT_NODE && isBlockTag((child as Element).tagName);
    if (isBlock) {
      flush();
    } else {
      run.push(child);
    }
  }
  flush();
}

export function setContent(root: HTMLElement, html: string): void {
  root.innerHTML = '';
  root.appendChild(sanitizeHtml(html));
  wrapLooseInlineContent(root);
}
