// Builds a TinyMCE-style breadcrumb of the block/inline elements that
// contain the current caret/selection, from outermost to innermost
// (e.g. root > p > a), for display as clickable path segments.
export function getElementPath(root: HTMLElement, node: Node | null): Element[] {
  const path: Element[] = [];
  let current: Node | null = node;

  while (current && current !== root) {
    if (current.nodeType === Node.ELEMENT_NODE) {
      path.unshift(current as Element);
    }
    current = current.parentNode;
  }

  return path;
}
