import { isSafeUrl } from './Schema';

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

export type MediaKind = 'embed' | 'video' | 'audio';

export interface MediaAttrs {
  url: string;
  poster?: string;
  width?: string;
  height?: string;
}

// Recognizes a share/watch URL from a known embeddable provider and returns
// its embeddable iframe src, or null if the URL doesn't match any of them.
// Each provider is tried in turn; order only matters in that Google Maps is
// checked before the generic Google Docs family since both share a host.
export function toEmbedUrl(url: string): string | null {
  const trimmed = url.trim();

  const youtube = trimmed.match(
    /(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([\w-]{6,})/,
  );
  if (youtube) return `https://www.youtube.com/embed/${youtube[1]}`;

  const vimeo = trimmed.match(/vimeo\.com\/(\d+)/);
  if (vimeo) return `https://player.vimeo.com/video/${vimeo[1]}`;

  // Google Maps share/place URLs don't have a stable embeddable form we can
  // derive without an API key, but a URL that's already a maps embed link
  // (e.g. pasted from Maps' own "Embed a map" panel) is passed through as-is.
  if (/^https:\/\/www\.google\.com\/maps\/embed/i.test(trimmed)) return trimmed;

  const codepen = trimmed.match(/codepen\.io\/([\w-]+)\/pen\/([\w-]+)/);
  if (codepen) return `https://codepen.io/${codepen[1]}/embed/${codepen[2]}`;

  const slides = trimmed.match(/docs\.google\.com\/presentation\/d\/([\w-]+)/);
  if (slides) return `https://docs.google.com/presentation/d/${slides[1]}/embed`;

  const docs = trimmed.match(/docs\.google\.com\/document\/d\/([\w-]+)/);
  if (docs) return `https://docs.google.com/document/d/${docs[1]}/embed`;

  const sheets = trimmed.match(/docs\.google\.com\/spreadsheets\/d\/([\w-]+)/);
  if (sheets) return `https://docs.google.com/spreadsheets/d/${sheets[1]}/embed`;

  const spotify = trimmed.match(/open\.spotify\.com\/(track|album|playlist|episode|show)\/([\w-]+)/);
  if (spotify) return `https://open.spotify.com/embed/${spotify[1]}/${spotify[2]}`;

  return null;
}

const VIDEO_FILE_EXTENSIONS = ['mp4', 'webm', 'ogg', 'ogv', 'mov', 'm4v'];
const AUDIO_FILE_EXTENSIONS = ['mp3', 'wav', 'ogg', 'oga', 'm4a', 'aac', 'flac'];

// True for a URL that looks like a direct, self-hosted video file (by
// extension) rather than a provider page — used to decide whether a
// pasted URL should become a native <video> element instead of an embed.
export function isDirectVideoUrl(url: string): boolean {
  const trimmed = url.trim().split(/[?#]/)[0] ?? '';
  const ext = trimmed.split('.').pop()?.toLowerCase();
  return !!ext && VIDEO_FILE_EXTENSIONS.includes(ext);
}

// Same idea as isDirectVideoUrl but for self-hosted audio files, used to
// route a pasted URL to a native <audio> element instead of <video>/embed.
// 'ogg' is ambiguous between audio and video containers; isDirectVideoUrl is
// always checked first by classifyMediaUrl so a bare .ogg URL is treated as
// video, matching the more common case.
export function isDirectAudioUrl(url: string): boolean {
  const trimmed = url.trim().split(/[?#]/)[0] ?? '';
  const ext = trimmed.split('.').pop()?.toLowerCase();
  return !!ext && AUDIO_FILE_EXTENSIONS.includes(ext);
}

// Classifies a URL the user typed into the media dialog: a recognized
// provider link becomes a responsive iframe embed, anything else (any
// video file URL, on any host — self-hosted, a CDN, S3, etc.) becomes a
// native <video controls> element playable via the browser's own player.
// This is deliberately permissive about the "video" case — TinyMCE's own
// media plugin similarly falls back to <video> for any non-provider URL
// rather than maintaining an exhaustive host/extension allowlist — while
// still routing every URL through isSafeUrl before it's ever used.
export function classifyMediaUrl(url: string): MediaKind | null {
  const trimmed = url.trim();
  if (!trimmed || !isSafeUrl(trimmed)) return null;
  if (toEmbedUrl(trimmed)) return 'embed';
  if (isDirectAudioUrl(trimmed) && !isDirectVideoUrl(trimmed)) return 'audio';
  // Accept any http(s) URL as a candidate self-hosted video; isSafeUrl
  // already screened out javascript:/data:/vbscript: schemes.
  if (/^https?:\/\//i.test(trimmed)) return 'video';
  return null;
}

function buildEmbedWrapper(embedUrl: string): HTMLElement {
  const wrapper = document.createElement('div');
  wrapper.className = 'omar-text-editor-media-embed';

  const iframe = document.createElement('iframe');
  iframe.src = embedUrl;
  iframe.setAttribute('frameborder', '0');
  iframe.setAttribute('allowfullscreen', 'true');
  iframe.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-presentation');
  wrapper.appendChild(iframe);
  return wrapper;
}

function buildVideoWrapper(attrs: MediaAttrs): HTMLElement {
  const wrapper = document.createElement('div');
  wrapper.className = 'omar-text-editor-media-video';

  const video = document.createElement('video');
  video.src = attrs.url;
  video.setAttribute('controls', '');
  video.setAttribute('preload', 'metadata');
  if (attrs.poster && isSafeUrl(attrs.poster)) video.setAttribute('poster', attrs.poster);
  if (attrs.width) video.style.width = /^\d+$/.test(attrs.width) ? `${attrs.width}px` : attrs.width;
  if (attrs.height) video.style.height = /^\d+$/.test(attrs.height) ? `${attrs.height}px` : attrs.height;
  wrapper.appendChild(video);
  return wrapper;
}

function buildAudioWrapper(attrs: MediaAttrs): HTMLElement {
  const wrapper = document.createElement('div');
  wrapper.className = 'omar-text-editor-media-audio';

  const audio = document.createElement('audio');
  audio.src = attrs.url;
  audio.setAttribute('controls', '');
  audio.setAttribute('preload', 'metadata');
  if (attrs.width) audio.style.width = /^\d+$/.test(attrs.width) ? `${attrs.width}px` : attrs.width;
  wrapper.appendChild(audio);
  return wrapper;
}

function buildWrapper(attrs: MediaAttrs): { wrapper: HTMLElement; kind: MediaKind } | null {
  const kind = classifyMediaUrl(attrs.url);
  if (!kind) return null;

  if (kind === 'embed') {
    const embedUrl = toEmbedUrl(attrs.url)!;
    return { wrapper: buildEmbedWrapper(embedUrl), kind };
  }
  if (kind === 'audio') {
    return { wrapper: buildAudioWrapper(attrs), kind };
  }
  return { wrapper: buildVideoWrapper(attrs), kind };
}

// Inserts a media element for `attrs.url`: a responsive provider embed
// (YouTube, Vimeo, Google Maps/Slides/Docs/Sheets, Spotify, CodePen), a
// native <video controls> for a direct video file URL, or a native
// <audio controls> for a direct audio file URL — with an optional poster
// image (video only). Returns false if the URL is unsafe or doesn't
// resolve to any of these kinds.
export function insertMediaEmbed(root: HTMLElement, attrs: MediaAttrs): boolean {
  const built = buildWrapper(attrs);
  if (!built) return false;

  const range = getRange();
  if (range) {
    range.deleteContents();
    range.insertNode(built.wrapper);
    range.setStartAfter(built.wrapper);
    range.collapse(true);
    const sel = window.getSelection();
    sel?.removeAllRanges();
    sel?.addRange(range);
  } else {
    root.appendChild(built.wrapper);
  }

  return true;
}

// Finds the media wrapper (embed OR video) the caret is currently
// inside/adjacent to, used to reopen the dialog pre-filled for editing and
// by the context menu — mirrors getSelectedImage's dual range/anchorNode
// lookup.
export function getSelectedMediaEmbed(root: HTMLElement): HTMLElement | null {
  const findWrapper = (node: Node | null): HTMLElement | null => {
    let current: Node | null = node;
    while (current && current !== root.parentNode) {
      if (
        current.nodeType === Node.ELEMENT_NODE &&
        ((current as Element).classList.contains('omar-text-editor-media-embed') ||
          (current as Element).classList.contains('omar-text-editor-media-video') ||
          (current as Element).classList.contains('omar-text-editor-media-audio'))
      ) {
        return current as HTMLElement;
      }
      current = current.parentNode;
    }
    return null;
  };

  const range = getRange();
  if (range) {
    const fromRange = findWrapper(range.startContainer);
    if (fromRange) return fromRange;
    const node = range.startContainer.nodeType === Node.ELEMENT_NODE
      ? range.startContainer.childNodes[range.startOffset]
      : null;
    if (node) {
      const fromChild = findWrapper(node);
      if (fromChild) return fromChild;
    }
  }

  const selection = window.getSelection();
  return findWrapper(selection?.anchorNode ?? null);
}

export function getMediaKind(wrapper: HTMLElement): MediaKind {
  if (wrapper.classList.contains('omar-text-editor-media-video')) return 'video';
  if (wrapper.classList.contains('omar-text-editor-media-audio')) return 'audio';
  return 'embed';
}

export function getEmbedUrl(wrapper: HTMLElement): string {
  const iframe = wrapper.querySelector('iframe');
  if (iframe) return iframe.getAttribute('src') ?? '';
  const video = wrapper.querySelector('video');
  if (video) return video.getAttribute('src') ?? '';
  return wrapper.querySelector('audio')?.getAttribute('src') ?? '';
}

export function getMediaAttrs(wrapper: HTMLElement): MediaAttrs {
  // The drag-resize handle (MediaResizer) sets width on the wrapper, not
  // the inner element, so it takes priority when present — otherwise the
  // Edit dialog's Width field would go stale/blank after a drag-resize.
  const wrapperWidth = wrapper.style.width || undefined;

  const video = wrapper.querySelector('video');
  if (video) {
    return {
      url: video.getAttribute('src') ?? '',
      poster: video.getAttribute('poster') ?? undefined,
      width: wrapperWidth ?? (video.style.width || undefined),
      height: video.style.height || undefined,
    };
  }
  const audio = wrapper.querySelector('audio');
  if (audio) {
    return {
      url: audio.getAttribute('src') ?? '',
      width: wrapperWidth ?? (audio.style.width || undefined),
    };
  }
  return { url: getEmbedUrl(wrapper), width: wrapperWidth };
}

// Replaces the wrapper's contents in place with a freshly-built embed or
// video element for the new attrs — rebuilding rather than patching
// individual attributes handles switching between an embed and a video
// (or vice versa) if the edited URL changes kind, not just updating a
// same-kind URL/poster/size.
export function updateMediaEmbed(wrapper: HTMLElement, attrs: MediaAttrs): boolean {
  const built = buildWrapper(attrs);
  if (!built) return false;

  wrapper.className = built.wrapper.className;
  wrapper.replaceChildren(...Array.from(built.wrapper.childNodes));
  // Clear any wrapper-level width set by a prior drag-resize: getMediaAttrs
  // surfaced it as the dialog's current Width value, so whatever the user
  // submitted (possibly unchanged, possibly edited) is now the sole source
  // of truth, applied to the inner element by buildWrapper above.
  wrapper.style.removeProperty('width');
  wrapper.style.removeProperty('max-width');
  return true;
}

export function removeMediaEmbed(wrapper: HTMLElement): void {
  wrapper.remove();
}

export type MediaAlign = 'left' | 'center' | 'right' | 'none';

// Same float-based alignment scheme as core/Images.ts's applyAlign, applied
// to the wrapper div rather than the media element itself, since the
// wrapper is what carries layout (width/aspect-ratio/margin) for all three
// kinds. Center is expressed as clearing any float and letting the
// wrapper's own width/max-width center it via margin auto.
export function setMediaAlign(wrapper: HTMLElement, align: MediaAlign): void {
  wrapper.style.removeProperty('float');
  wrapper.style.removeProperty('margin-left');
  wrapper.style.removeProperty('margin-right');

  if (align === 'left') {
    wrapper.style.float = 'left';
    wrapper.style.marginRight = '12px';
  } else if (align === 'right') {
    wrapper.style.float = 'right';
    wrapper.style.marginLeft = '12px';
  } else if (align === 'center') {
    wrapper.style.marginLeft = 'auto';
    wrapper.style.marginRight = 'auto';
  }
}

export function getMediaAlign(wrapper: HTMLElement): MediaAlign {
  if (wrapper.style.float === 'left') return 'left';
  if (wrapper.style.float === 'right') return 'right';
  if (wrapper.style.marginLeft === 'auto') return 'center';
  return 'none';
}

// Sets the wrapper's overall width (used by the drag-resize handle) —
// applies to the wrapper div for all three kinds, since that's what
// controls displayed size (the embed iframe fills it via inset:0; the
// video/audio element inside is `max-width: 100%` so it shrinks to fit).
export function setMediaWidth(wrapper: HTMLElement, widthPx: number): void {
  const clamped = Math.max(80, Math.round(widthPx));
  wrapper.style.width = `${clamped}px`;
  wrapper.style.maxWidth = `${clamped}px`;
}

// Stretches the wrapper to the full width of the content area — clears any
// explicit/drag-resized width and overrides the theme's default
// max-width cap (640px for embeds/video) with `none`, rather than just
// clearing max-width back to that default.
export function setMediaFullWidth(wrapper: HTMLElement): void {
  wrapper.style.width = '100%';
  wrapper.style.maxWidth = 'none';
}

export function isMediaFullWidth(wrapper: HTMLElement): boolean {
  return wrapper.style.width === '100%' && wrapper.style.maxWidth === 'none';
}
