import type { Editor } from '../../core/Editor';
import { registerPlugin } from '../../core/Editor';
import { Dialog } from '../../ui/Dialog';
import { Notification } from '../../ui/Notification';
import { registerToolbarButton } from '../../ui/Toolbar';
import { insertOrUpdateLink, removeLink, getCurrentLink, isLinkActive } from '../../core/Links';
import { tryAutolink } from '../../core/Autolink';
import { bookmarkSelection, restoreSelection } from '../../core/Selection';

// Opens the Insert/Edit Link dialog, pre-filled from the link at the caret
// if one exists, and applies the result via core/Links.
export function openLinkDialog(editor: Editor): void {
  const root = editor.getEditableElement();
  const existing = getCurrentLink(root);
  const sel = window.getSelection();
  const selectedText = sel && !sel.isCollapsed ? sel.toString() : '';
  const bookmark = bookmarkSelection(root);

  new Dialog({
    title: existing ? 'Edit Link' : 'Insert Link',
    submitLabel: existing ? 'Update' : 'Insert',
    fields: [
      { name: 'href', label: 'URL', type: 'text', defaultValue: existing?.getAttribute('href') ?? '' },
      {
        name: 'text', label: 'Text to display', type: 'text',
        defaultValue: existing?.textContent ?? selectedText,
      },
      { name: 'title', label: 'Title', type: 'text', defaultValue: existing?.getAttribute('title') ?? '' },
      {
        name: 'newTab', label: 'Open in new tab', type: 'checkbox',
        defaultValue: existing?.getAttribute('target') === '_blank',
      },
    ],
    onSubmit: (values) => {
      root.focus();
      if (bookmark) restoreSelection(root, bookmark);
      const ok = insertOrUpdateLink(root, {
        href: String(values.href).trim(),
        text: String(values.text ?? '').trim(),
        title: String(values.title ?? '').trim() || undefined,
        newTab: !!values.newTab,
      });

      if (!ok) {
        new Notification({ message: 'Please enter a valid URL.', type: 'error' });
        return;
      }

      editor.execCommand('__syncAfterExternalEdit');
    },
  });
}

export function removeLinkAtCaret(editor: Editor): void {
  const root = editor.getEditableElement();
  root.focus();
  if (removeLink(root)) {
    editor.execCommand('__syncAfterExternalEdit');
  }
}

export function isAnyLinkActive(editor: Editor): boolean {
  return isLinkActive(editor.getEditableElement());
}

// Wires autolink: after typing a space or Enter, checks whether the text
// just before the caret looks like a bare URL/email and wraps it.
export function setupAutolink(editor: Editor): void {
  const root = editor.getEditableElement();

  root.addEventListener('keyup', (e: KeyboardEvent) => {
    if (e.key !== ' ' && e.key !== 'Enter') return;

    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0 || !sel.isCollapsed) return;

    const range = sel.getRangeAt(0);
    const node = range.startContainer;
    if (node.nodeType !== Node.TEXT_NODE) return;

    // The trigger character was already inserted; look at the text just
    // before it (offset - 1) as the boundary for the candidate match.
    const offset = Math.max(0, range.startOffset - 1);
    if (tryAutolink(root, node as Text, offset)) {
      editor.execCommand('__syncAfterExternalEdit');
    }
  });
}

registerToolbarButton({
  name: 'link', label: 'Insert/edit link', icon: 'link', command: 'link',
  isActive: (e) => e.isLinkActive(),
});

registerToolbarButton({ name: 'unlink', label: 'Remove link', icon: 'unlink', command: 'unlink' });

registerPlugin('link', (editor) => {
  editor.commands.register('link', () => openLinkDialog(editor));
  editor.commands.register('unlink', () => removeLinkAtCaret(editor));
  setupAutolink(editor);
});

registerPlugin('autolink', (editor) => {
  setupAutolink(editor);
});
