import { resizeRow } from '../core/Tables';

interface TrackedHandle {
  el: HTMLElement;
  table: HTMLTableElement;
  rowIndex: number;
}

// Adds a thin draggable handle over each row border of every table inside
// `root`, mirroring ColumnResizer but for row height instead of column
// width. Handles are re-scanned whenever the editable content changes (call
// `refresh()` after structural edits).
export class RowResizer {
  private handles: TrackedHandle[] = [];
  private onCommit: (() => void) | null = null;
  // See ColumnResizer's identical field: keeps handle positions in sync
  // with layout changes (e.g. content reflow) that don't fire `input`.
  private resizeObserver: ResizeObserver | null =
    typeof ResizeObserver !== 'undefined' ? new ResizeObserver(() => this.repositionAll()) : null;

  constructor(private root: HTMLElement) {
    this.refresh();
    root.addEventListener('input', () => this.refresh());
  }

  onResizeCommit(cb: () => void): void {
    this.onCommit = cb;
  }

  refresh(): void {
    this.clearHandles();
    const tables = this.root.querySelectorAll('table');
    tables.forEach((table) => {
      this.resizeObserver?.observe(table);
      this.attachHandles(table as HTMLTableElement);
    });
  }

  private repositionAll(): void {
    for (const handle of this.handles) {
      this.positionHandle(handle.el, handle.table, handle.rowIndex);
    }
  }

  private clearHandles(): void {
    this.handles.forEach((h) => h.el.remove());
    this.handles = [];
    this.resizeObserver?.disconnect();
  }

  private attachHandles(table: HTMLTableElement): void {
    const rows = table.querySelectorAll('tr');
    if (rows.length === 0) return;

    (table.style as CSSStyleDeclaration).position = 'relative';

    for (let i = 0; i < rows.length - 1; i++) {
      const handle = document.createElement('div');
      handle.className = 'omar-text-editor-row-resize-handle';
      table.parentElement?.style.setProperty('position', 'relative');
      this.positionHandle(handle, table, i);
      handle.addEventListener('mousedown', (e) => this.startDrag(e, table, i));
      table.parentElement?.appendChild(handle);
      this.handles.push({ el: handle, table, rowIndex: i });
    }
  }

  private positionHandle(handle: HTMLElement, table: HTMLTableElement, rowIndex: number): void {
    const row = table.querySelectorAll('tr')[rowIndex] as HTMLElement | undefined;
    const parent = table.parentElement;
    if (!row || !parent) return;

    const tableRect = table.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    const parentRect = parent.getBoundingClientRect();

    handle.style.top = `${rowRect.bottom - parentRect.top - 3}px`;
    handle.style.left = `${tableRect.left - parentRect.left}px`;
    handle.style.width = `${tableRect.width}px`;
  }

  private startDrag(e: MouseEvent, table: HTMLTableElement, rowIndex: number): void {
    e.preventDefault();
    e.stopPropagation();
    const row = table.querySelectorAll('tr')[rowIndex] as HTMLElement;
    const startY = e.clientY;
    const startHeight = row.getBoundingClientRect().height;

    const onMouseMove = (moveEvent: MouseEvent) => {
      const delta = moveEvent.clientY - startY;
      resizeRow(table, rowIndex, startHeight + delta);
      this.repositionAll();
    };

    const onMouseUp = () => {
      document.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('mouseup', onMouseUp);
      this.onCommit?.();
    };

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  }

  destroy(): void {
    this.clearHandles();
  }
}
