// Detects a bare URL or email address immediately preceding the caret
// (typically triggered right after typing a space/newline that follows
// the URL) and wraps it in an <a> element automatically.

const URL_PATTERN = /(https?:\/\/[^\s<]+|www\.[^\s<]+)$/i;
const EMAIL_PATTERN = /([\w.+-]+@[\w-]+\.[a-z]{2,})$/i;

function normalizeHref(match: string): string {
  if (EMAIL_PATTERN.test(match) && !match.includes('://')) {
    return `mailto:${match}`;
  }
  if (match.toLowerCase().startsWith('www.')) {
    return `https://${match}`;
  }
  return match;
}

// Call this after a trigger character (space, Enter) has been typed.
// `textNode` is the text node the caret was in just before the trigger
// character; `caretOffset` is where the caret was (i.e. the boundary
// right after the candidate URL/email, before the trigger char).
export function tryAutolink(root: HTMLElement, textNode: Text, caretOffset: number): boolean {
  const textBefore = textNode.data.slice(0, caretOffset);

  const urlMatch = textBefore.match(URL_PATTERN);
  const emailMatch = !urlMatch ? textBefore.match(EMAIL_PATTERN) : null;
  const match = urlMatch?.[0] ?? emailMatch?.[0];
  if (!match) return false;

  const matchStart = caretOffset - match.length;

  const range = document.createRange();
  range.setStart(textNode, matchStart);
  range.setEnd(textNode, caretOffset);

  const a = document.createElement('a');
  a.setAttribute('href', normalizeHref(match));
  a.textContent = match;

  range.deleteContents();
  range.insertNode(a);

  // Leave the caret positioned right after the newly created link, where
  // the trigger character (space/newline) will land next.
  const caretRange = document.createRange();
  caretRange.setStartAfter(a);
  caretRange.collapse(true);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(caretRange);

  return true;
}
