export type CommandHandler = (value?: string) => void;

// Registry of editor commands. Phase 1 ships the bare minimum (bold/italic/
// underline/undo/redo); later phases register more via `register()`.
export class Commands {
  private handlers = new Map<string, CommandHandler>();

  register(name: string, handler: CommandHandler): void {
    this.handlers.set(name, handler);
  }

  has(name: string): boolean {
    return this.handlers.has(name);
  }

  exec(name: string, value?: string): boolean {
    const handler = this.handlers.get(name);
    if (!handler) return false;
    handler(value);
    return true;
  }
}
