// A thin bar below the editable area for status text (word/char counts,
// and any future status segments). Multiple plugins can each own a named
// segment.
export class StatusBar {
  readonly el: HTMLElement;
  private segments = new Map<string, HTMLElement>();
  private branding: HTMLAnchorElement;

  constructor() {
    this.el = document.createElement('div');
    this.el.className = 'omar-text-editor-statusbar';

    // Pinned to the far right regardless of what other segments a plugin
    // adds/removes, matching the "Powered by X" attribution convention
    // used at the bottom-right of most rich text editors. Must stay the
    // LAST child (re-appended after every new segment below) — margin-left:
    // auto only pushes itself right of its own position, so every segment
    // has to sit before it in DOM order for the left side to stay left.
    this.branding = document.createElement('a');
    this.branding.className = 'omar-text-editor-statusbar-branding';
    this.branding.href = 'https://github.com/wholeomarfaruk';
    this.branding.target = '_blank';
    this.branding.rel = 'noopener noreferrer';
    this.branding.textContent = 'Powered by Omar Text Editor';
    this.el.appendChild(this.branding);
  }

  setSegment(name: string, text: string): void {
    const segment = this.getOrCreateSegment(name);
    segment.textContent = text;
  }

  // Like setSegment, but lets the caller populate the segment with child
  // elements (e.g. clickable breadcrumb links) instead of plain text.
  setSegmentContent(name: string, children: Node[]): void {
    const segment = this.getOrCreateSegment(name);
    segment.replaceChildren(...children);
  }

  private getOrCreateSegment(name: string): HTMLElement {
    let segment = this.segments.get(name);
    if (!segment) {
      segment = document.createElement('span');
      segment.className = 'omar-text-editor-statusbar-segment';
      this.segments.set(name, segment);
      this.el.insertBefore(segment, this.branding);
    }
    return segment;
  }

  destroy(): void {
    this.el.remove();
  }
}
