export interface ContextMenuItem {
  label: string;
  onSelect: () => void;
  separator?: boolean;
}

// A right-click menu framework: positions itself at the click point, closes
// on outside click / Esc / item selection. Used later by table/image
// plugins for cell/row/column operations.
export class ContextMenu {
  private el: HTMLElement;

  constructor(x: number, y: number, items: ContextMenuItem[]) {
    this.el = document.createElement('div');
    this.el.className = 'omar-text-editor-context-menu';
    this.el.style.left = `${x}px`;
    this.el.style.top = `${y}px`;

    for (const item of items) {
      if (item.separator) {
        const sep = document.createElement('div');
        sep.className = 'omar-text-editor-context-menu-separator';
        this.el.appendChild(sep);
        continue;
      }
      const entry = document.createElement('button');
      entry.type = 'button';
      entry.className = 'omar-text-editor-context-menu-item';
      entry.textContent = item.label;
      entry.addEventListener('click', () => {
        item.onSelect();
        this.close();
      });
      this.el.appendChild(entry);
    }

    document.body.appendChild(this.el);
    this.clampToViewport();

    document.addEventListener('mousedown', this.handleOutsideClick);
    document.addEventListener('keydown', this.handleKeydown);
  }

  private clampToViewport(): void {
    const rect = this.el.getBoundingClientRect();
    const overflowX = rect.right - window.innerWidth;
    const overflowY = rect.bottom - window.innerHeight;
    if (overflowX > 0) this.el.style.left = `${rect.left - overflowX}px`;
    if (overflowY > 0) this.el.style.top = `${rect.top - overflowY}px`;
  }

  private handleOutsideClick = (e: MouseEvent): void => {
    if (!this.el.contains(e.target as Node)) this.close();
  };

  private handleKeydown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') this.close();
  };

  close(): void {
    document.removeEventListener('mousedown', this.handleOutsideClick);
    document.removeEventListener('keydown', this.handleKeydown);
    this.el.remove();
  }
}
