const RECENT_KEY = 'omar-text-editor-recent-emoji';
const MAX_RECENT = 16;

export function searchEmoji(query: string): Emoji[] {
  const q = query.trim().toLowerCase();
  if (!q) return EMOJI_LIST;
  return EMOJI_LIST.filter(
    (e) => e.name.includes(q) || e.keywords.some((k) => k.includes(q)),
  );
}

export function getRecentEmoji(): Emoji[] {
  try {
    const raw = localStorage.getItem(RECENT_KEY);
    if (!raw) return [];
    const chars: string[] = JSON.parse(raw);
    return chars
      .map((c) => EMOJI_LIST.find((e) => e.char === c))
      .filter((e): e is Emoji => !!e);
  } catch {
    return [];
  }
}

export function recordRecentEmoji(char: string): void {
  try {
    const current = getRecentEmoji().map((e) => e.char).filter((c) => c !== char);
    const updated = [char, ...current].slice(0, MAX_RECENT);
    localStorage.setItem(RECENT_KEY, JSON.stringify(updated));
  } catch {
    // localStorage unavailable (private mode, quota) — recent list is a
    // convenience feature, safe to silently skip persisting it.
  }
}
