// Whitelist of elements/attributes allowed to survive sanitization.
// Kept intentionally small in Phase 1; plugins extend this as they land.

export const ALLOWED_TAGS = new Set([
  'p', 'br', 'div', 'span',
  'strong', 'b', 'em', 'i', 'u', 's', 'strike', 'sup', 'sub', 'code',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
  'ul', 'ol', 'li',
  'a', 'img',
  'blockquote', 'pre', 'hr',
  'table', 'thead', 'tbody', 'tr', 'td', 'th',
  'iframe',
  'video', 'audio', 'source',
]);

export const ALLOWED_ATTRS = new Set([
  'href', 'target', 'rel', 'title',
  'src', 'alt', 'width', 'height',
  'id', 'class', 'style',
  'colspan', 'rowspan',
  'frameborder', 'allowfullscreen', 'sandbox',
  'controls', 'poster', 'preload', 'loop', 'muted', 'playsinline', 'type',
]);

const BLOCKED_URL_SCHEMES = ['javascript:', 'data:text/html', 'vbscript:'];

export function isSafeUrl(url: string): boolean {
  const normalized = url.trim().toLowerCase();
  return !BLOCKED_URL_SCHEMES.some((scheme) => normalized.startsWith(scheme));
}

// <iframe> is only ever allowed to survive sanitization for our own
// trusted embeds (see core/Media.ts and core/Embed.ts) — never for
// arbitrary pasted or hand-typed iframe HTML, which would otherwise be a
// wide-open injection vector. Anything whose src doesn't match a known
// embed host is treated as unsafe and the element is dropped entirely (not
// just unwrapped, since an iframe has no meaningful "unwrapped" content).
// This is the single source of truth for allowed embed hosts — Media.ts's
// provider detection and Embed.ts's pasted-code validation both check
// against this same list rather than keeping their own copy.
export const ALLOWED_IFRAME_SRC_PREFIXES = [
  'https://www.youtube.com/embed/',
  'https://player.vimeo.com/video/',
  'https://www.google.com/maps/embed',
  'https://codepen.io/',
  'https://docs.google.com/presentation/d/',
  'https://docs.google.com/document/d/',
  'https://docs.google.com/spreadsheets/d/',
  'https://open.spotify.com/embed/',
];

// Human-readable provider names, in the same order as the prefixes above,
// for surfacing in dialog help text without hardcoding a second list.
export const IFRAME_EMBED_PROVIDER_NAMES = [
  'YouTube', 'Vimeo', 'Google Maps', 'CodePen', 'Google Slides', 'Google Docs', 'Google Sheets', 'Spotify',
];

export function isAllowedIframeSrc(src: string): boolean {
  const normalized = src.trim().toLowerCase();
  return ALLOWED_IFRAME_SRC_PREFIXES.some((prefix) => normalized.startsWith(prefix));
}

// A style attribute value is otherwise-unrestricted CSS text, which can
// itself carry an executable payload: url(javascript:...) as a background
// image, or the legacy IE-only expression(...) function. Rather than
// trying to fully parse CSS, this rejects the whole style value if it
// contains any red flag — safe-by-refusal, since a formatting feature
// losing an inline style is a much smaller cost than an XSS hole.
const UNSAFE_STYLE_PATTERNS = [/expression\s*\(/i, /javascript:/i, /vbscript:/i, /<script/i];

export function isSafeStyleValue(value: string): boolean {
  return !UNSAFE_STYLE_PATTERNS.some((pattern) => pattern.test(value));
}

export const BLOCK_TAGS = new Set([
  'p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
  'ul', 'ol', 'li', 'blockquote', 'pre', 'table', 'hr',
]);

export function isBlockTag(tagName: string): boolean {
  return BLOCK_TAGS.has(tagName.toLowerCase());
}
