export function searchCharMap(query: string): SpecialChar[] {
  const q = query.trim().toLowerCase();
  if (!q) return CHAR_MAP_LIST;
  return CHAR_MAP_LIST.filter(
    (c) => c.name.includes(q) || c.code.toLowerCase().includes(q),
  );
}
