import { isBlockTag } from './Schema';

export interface CountResult {
  words: number;
  characters: number;
  charactersNoSpaces: number;
}

// Concatenates text for word-counting purposes, inserting a space at each
// block-element boundary. Without this, adjacent blocks like
// "<p>One two</p><p>three</p>" would run together as "twothree" via plain
// textContent, undercounting words by however many block boundaries exist.
function extractWordCountText(node: Node): string {
  let result = '';

  for (const child of Array.from(node.childNodes)) {
    if (child.nodeType === Node.TEXT_NODE) {
      result += child.textContent ?? '';
    } else if (child.nodeType === Node.ELEMENT_NODE) {
      const tag = (child as Element).tagName.toLowerCase();
      result += extractWordCountText(child);
      if (isBlockTag(tag) || tag === 'br') result += ' ';
    }
  }

  return result;
}

export function countText(root: HTMLElement): CountResult {
  const wordText = extractWordCountText(root);
  const trimmedWordText = wordText.trim();
  const words = trimmedWordText.length === 0 ? 0 : trimmedWordText.split(/\s+/).length;

  const rawText = root.textContent ?? '';
  const characters = rawText.length;
  const charactersNoSpaces = rawText.replace(/\s/g, '').length;

  return { words, characters, charactersNoSpaces };
}
