export function getIconSvg(name: string): string {
  const path = ICONS[name];
  if (!path) return '';
  return `<svg viewBox="0 0 20 20" width="18" height="18" fill="currentColor" aria-hidden="true">${path}</svg>`;
}

export function hasIcon(name: string): boolean {
  return name in ICONS;
}

export function registerIcon(name: string, svgPathMarkup: string): void {
  ICONS[name] = svgPathMarkup;
}
